def main():
    os.makedirs(DESTINO, exist_ok=True)
    salida = {}
    n = 0
    for f in sorted(os.listdir(ORIGEN)):
        if not f.lower().endswith('.pcx'):
            continue
        nombre = f[:-4]
        ruta = os.path.join(ORIGEN, f)
        im = decode(ruta)
        im.save(os.path.join(DESTINO, nombre + '.png'))
        d = open(ruta, 'rb').read(88)
        flag = struct.unpack('<H', d[76:78])[0]
        info = {'png': nombre + '.png', 'ancho': im.width, 'alto': im.height, 'bpp': 8 if flag & 1 else 4, 'semi': modo_semi(ruta)}
        info.update(POS.get(nombre, {'uso': 'sin referencia en open.c'}))
        salida[nombre] = info
        n += 1
    meta = {'_nota': 'pantalla = rectángulo en 320x224 (origen arriba-izquierda; el juego usa el centro 160,112) donde open.c dibuja la textura; capa = valor de la tabla de orden (mayor = más atrás); tinte = color del polígono (128 = textura tal cual); semi = modo de la cabecera .pcx (0 50/50, 1 aditivo, 2 resta, 3 +1/4).', 'origen': os.path.relpath(ORIGEN, RAIZ), 'texturas': salida}
    with open(os.path.join(DESTINO, 'titulo.json'), 'w', encoding='utf-8') as fh:
        json.dump(meta, fh, ensure_ascii=False, indent=1)
    print(f'{n} texturas exportadas a {os.path.relpath(DESTINO, RAIZ)} + titulo.json')
if __name__ == '__main__':
    main()
